package com.travelbird.ai.controller;
import com.travelbird.ai.dto.request.*;import com.travelbird.ai.dto.response.*;import com.travelbird.ai.service.AiPreviewService;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/ai/trip-previews") public class AiPreviewController{private final AiPreviewService service;public AiPreviewController(AiPreviewService s){service=s;}@GetMapping("/{previewId}")public AiPreviewResponse get(@AuthenticationPrincipal Long userId,@PathVariable Long previewId){return service.get(userId,previewId);}@PatchMapping("/{previewId}")public AiPreviewResponse update(@AuthenticationPrincipal Long userId,@PathVariable Long previewId,@RequestBody UpdateAiTripPreviewRequest r){return service.update(userId,previewId,r);}@PostMapping("/{previewId}/apply")public ApplyAiPreviewResponse apply(@AuthenticationPrincipal Long userId,@PathVariable Long previewId){return service.apply(userId,previewId);}}

